-- ICT Technical Paper II short answers follow the latest (BCSE 2025) layout: Part II = 6 questions x 5 marks = 30
-- (founder rule, 23 Nov 2026: every paper follows the latest year's style, format and marking). Each question (or
-- multi-part question) is set to 5 marks; key points, marks shown in the stem and rubric are scaled to match.
begin;
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Outline any three prerequisites to configure a server. (5 marks)', key_points = '[{"marks": 2, "point": "Suitable hardware and network: server hardware with enough CPU/RAM/storage, power backup (UPS), network connection"}, {"marks": 1.5, "point": "Operating system and software: server OS installed and updated, required roles/ services (web, DNS, DHCP, database), licences"}, {"marks": 1.5, "point": "Network and security settings: static IP address, hostname and DNS, firewall rules, administrator accounts and strong passwords, backup plan"}]'::jsonb where id = '94a8aba5-46e8-4de4-a171-ad02a2ac25b0';
delete from public.rubric_criteria where question_id = '94a8aba5-46e8-4de4-a171-ad02a2ac25b0';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Write the 6 stages of the Software Development Life Cycle (SDLC). (5 marks)', key_points = '[{"marks": 2, "point": "Planning/ requirement analysis; system analysis (requirements specification)"}, {"marks": 1.5, "point": "Design; implementation (coding)"}, {"marks": 1.5, "point": "Testing; deployment and maintenance"}]'::jsonb where id = 'bdb90249-1caa-454c-ac2f-e5bbbb170d3f';
delete from public.rubric_criteria where question_id = 'bdb90249-1caa-454c-ac2f-e5bbbb170d3f';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Name 3 relationships of a database. (5 marks)', key_points = '[{"marks": 2, "point": "One-to-one (1:1) - e.g. one person has one passport"}, {"marks": 1.5, "point": "One-to-many (1:M) - e.g. one department has many employees"}, {"marks": 1.5, "point": "Many-to-many (M:N) - e.g. students and courses (implemented with a junction table)"}]'::jsonb where id = '383cea17-b7bd-429e-86ed-53e416533e91';
delete from public.rubric_criteria where question_id = '383cea17-b7bd-429e-86ed-53e416533e91';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'What is the equivalent code of the following statement in WHILE LOOP format? Write the output of the program when executed.
for (a = 1; a <= 10; a++)
    printf("%d\n", a * a); (5 marks)', key_points = '[{"marks": 2, "point": "Initialisation before the loop: a = 1; while (a <= 10)"}, {"marks": 1.5, "point": "Body prints a * a and then increments a (a++)"}, {"marks": 1.5, "point": "Output: the squares 1, 4, 9, 16, 25, 36, 49, 64, 81, 100, each on a new line"}]'::jsonb where id = '4314081d-f0c7-4482-9176-8b75ca9acd00';
delete from public.rubric_criteria where question_id = '4314081d-f0c7-4482-9176-8b75ca9acd00';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Provide some advantages of IPv6 over IPv4. (5 marks)', key_points = '[{"marks": 2, "point": "Much larger address space: 128-bit addresses (about 3.4 × 10^38) vs 32-bit, ending address shortage and the need for NAT"}, {"marks": 1.5, "point": "Simpler, more efficient header and routing; no broadcast (multicast/ anycast instead); built-in stateless auto-configuration"}, {"marks": 1.5, "point": "Built-in security (IPsec), better quality of service (flow label) and mobility support"}]'::jsonb where id = 'f83db4a5-9228-4142-8bc7-02e8976af311';
delete from public.rubric_criteria where question_id = 'f83db4a5-9228-4142-8bc7-02e8976af311';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Briefly explain the terms unicasting, multicasting and broadcasting. (5 marks)', key_points = '[{"marks": 2, "point": "Unicasting: one-to-one - data sent from one sender to a single specific receiver (e.g. web browsing)"}, {"marks": 1.5, "point": "Multicasting: one-to-many - data sent to a selected group of receivers that joined a multicast group (e.g. IPTV, video conferencing)"}, {"marks": 1.5, "point": "Broadcasting: one-to-all - data sent to every device on the network segment (e.g. ARP request, 255.255.255.255)"}]'::jsonb where id = '6f2a91e5-46b6-4463-98ee-b0717a221d25';
delete from public.rubric_criteria where question_id = '6f2a91e5-46b6-4463-98ee-b0717a221d25';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'How does the Dynamic Host Configuration Protocol (DHCP) help in network administration? (5 marks)', key_points = '[{"marks": 2, "point": "DHCP automatically assigns IP addresses and configuration (subnet mask, default gateway, DNS) to devices from a pool"}, {"marks": 1.5, "point": "Saves administrators manual work and prevents errors such as duplicate IP addresses; easy to add/ move devices"}, {"marks": 1.5, "point": "Central management: leases reuse addresses, reservations for servers/ printers, changes made once at the server (DORA process)"}]'::jsonb where id = '69d78611-2d71-4817-92c3-cb37b3de874f';
delete from public.rubric_criteria where question_id = '69d78611-2d71-4817-92c3-cb37b3de874f';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'In what ways do fibre optics have advantages over other transmission media? (5 marks)', key_points = '[{"marks": 2, "point": "Much higher bandwidth and data rates over longer distances with low signal loss (attenuation)"}, {"marks": 1.5, "point": "Immune to electromagnetic interference and lightning; no crosstalk"}, {"marks": 1.5, "point": "More secure (hard to tap), light weight and thin, no corrosion/ sparks; any one"}]'::jsonb where id = '2dd94e1c-c9b2-496e-ab0c-e679f7169d29';
delete from public.rubric_criteria where question_id = '2dd94e1c-c9b2-496e-ab0c-e679f7169d29';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Why do we need to implement a fault-tolerant system? State some of its limitations. (5 marks)', key_points = '[{"marks": 2.5, "point": "Need: keeps the system working when a component fails - high availability, no data loss, continuity of critical services (banking, hospitals, government), reliability"}, {"marks": 2.5, "point": "Limitations: higher cost (redundant hardware, software, power), more complexity to design and maintain, extra space/ energy, may not cover every failure (common-mode failures), reduced performance from replication"}]'::jsonb where id = '025b1f17-4b36-48b8-b172-b1909d198dd4';
delete from public.rubric_criteria where question_id = '025b1f17-4b36-48b8-b172-b1909d198dd4';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Differentiate between communication and transmission. (5 marks)', key_points = '[{"marks": 2.5, "point": "Communication: the whole process of exchanging meaningful information between a sender and receiver, involving message, sender, receiver, medium and protocol (understanding)"}, {"marks": 2.5, "point": "Transmission: the physical sending of signals/ data over a medium from one point to another (one part of communication), concerned with signals, bandwidth and media"}]'::jsonb where id = '1dc579f7-253f-4e65-85c8-29995ef9df78';
delete from public.rubric_criteria where question_id = '1dc579f7-253f-4e65-85c8-29995ef9df78';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'What are the differences between single-mode fibre and multimode fibre? Mention three differences. (5 marks)', key_points = '[{"marks": 2, "point": "Core size: single-mode has a very small core (about 8-10 µm) carrying one light path; multimode has a larger core (50 or 62.5 µm) carrying many paths"}, {"marks": 1.5, "point": "Distance and bandwidth: single-mode goes much further (tens of km) with higher bandwidth; multimode is for short distances (up to about 550 m) because of modal dispersion"}, {"marks": 1.5, "point": "Light source and cost: single-mode uses lasers and is more expensive equipment; multimode uses LEDs/ VCSELs and is cheaper"}]'::jsonb where id = 'afe68b5c-5fee-4efc-bc08-364d8fe5555f';
delete from public.rubric_criteria where question_id = 'afe68b5c-5fee-4efc-bc08-364d8fe5555f';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'What do you mean by a hypervisor? What is the main difference between Type 1 and Type 2 hypervisors? Give one example of each. (5 marks)', key_points = '[{"marks": 2, "point": "Hypervisor (virtual machine monitor): software that creates and runs virtual machines, sharing physical hardware between several guest operating systems"}, {"marks": 1.5, "point": "Type 1 (bare-metal) runs directly on the hardware; Type 2 (hosted) runs on top of a host operating system - Type 1 is faster and used in data centres"}, {"marks": 1.5, "point": "Examples: Type 1 - VMware ESXi, Microsoft Hyper-V, Xen, KVM; Type 2 - Oracle VirtualBox, VMware Workstation, Parallels"}]'::jsonb where id = 'f89f4ea9-e874-472e-be06-867e6a054c6e';
delete from public.rubric_criteria where question_id = 'f89f4ea9-e874-472e-be06-867e6a054c6e';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Car A starts driving at a speed of 50 km/hr. A second car B starts 30 minutes later and catches car A after 30 minutes. What is the speed of car B? (5 marks)', key_points = '[{"marks": 2.5, "point": "When B catches A, A has driven 1 hour (30 + 30 minutes): distance = 50 × 1 = 50 km"}, {"marks": 2.5, "point": "B covers the same 50 km in 30 minutes (0.5 h): speed = 50 / 0.5 = 100 km/hr"}]'::jsonb where id = 'c16476bf-7093-452e-a9d6-b8eae4bcb75a';
delete from public.rubric_criteria where question_id = 'c16476bf-7093-452e-a9d6-b8eae4bcb75a';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'What are the key differences between TCP and UDP? (5 marks)', key_points = '[{"marks": 2, "point": "TCP is connection-oriented (three-way handshake); UDP is connectionless"}, {"marks": 1.5, "point": "TCP is reliable - acknowledgements, retransmission, ordering, flow and congestion control; UDP has no guarantee of delivery or order"}, {"marks": 1.5, "point": "TCP is slower with a larger header (20+ bytes) - used for web, email, file transfer; UDP is faster with an 8-byte header - used for DNS, streaming, VoIP, games"}]'::jsonb where id = 'e1fd1c8d-3420-49f3-a32e-e7e141eb2473';
delete from public.rubric_criteria where question_id = 'e1fd1c8d-3420-49f3-a32e-e7e141eb2473';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Explain the TCP three-way handshake process. (5 marks)', key_points = '[{"marks": 2, "point": "Step 1 SYN: the client sends a segment with the SYN flag and its initial sequence number (x)"}, {"marks": 1.5, "point": "Step 2 SYN-ACK: the server replies with SYN and ACK, its own sequence number (y) and acknowledgement x + 1"}, {"marks": 1.5, "point": "Step 3 ACK: the client sends ACK (acknowledgement y + 1); the connection is established and data transfer begins"}]'::jsonb where id = 'daec194d-b0e4-4f53-bdc3-6bc58c46a5b0';
delete from public.rubric_criteria where question_id = 'daec194d-b0e4-4f53-bdc3-6bc58c46a5b0';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Write HTML code to generate the following output (shown in the figure). Put table border as 1. (5 marks)', key_points = '[{"marks": 2, "point": "<table border=\"1\"> with a caption or first row ''Monthly Savings'' spanning 3 columns"}, {"marks": 1.5, "point": "Header row with <th>: Month, Savings, Savings for holiday!"}, {"marks": 1.5, "point": "Rows January $100 and February $80, with ''$50'' in one cell spanning both rows (rowspan=\"2\")"}]'::jsonb where id = '4b0736cd-433c-498d-a58e-bcd4c8437996';
delete from public.rubric_criteria where question_id = '4b0736cd-433c-498d-a58e-bcd4c8437996';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'What is cryptojacking? Explain how it works. (5 marks)', key_points = '[{"marks": 2, "point": "Definition: unauthorised use of someone''s computer, phone or server to mine cryptocurrency"}, {"marks": 1.5, "point": "How: malicious script/ malware installed through phishing links, infected websites or ads (browser-based JavaScript) or compromised servers/ cloud accounts"}, {"marks": 1.5, "point": "It runs silently using CPU/ GPU power, sending mined coins to the attacker; signs - slow device, overheating, high electricity/ cloud bills; prevention - ad/ script blockers, updates, antivirus, monitoring"}]'::jsonb where id = 'c3816df0-c641-46a1-be37-250d3394bdc9';
delete from public.rubric_criteria where question_id = 'c3816df0-c641-46a1-be37-250d3394bdc9';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'There are seven layers in the OSI model starting with the Physical Layer. Write the six other layers. (5 marks)', key_points = '[{"marks": 2, "point": "Data Link (layer 2), Network (layer 3)"}, {"marks": 1.5, "point": "Transport (layer 4), Session (layer 5)"}, {"marks": 1.5, "point": "Presentation (layer 6), Application (layer 7)"}]'::jsonb where id = 'ddd3fd8d-da72-41d0-88d6-5b1fea41c38d';
delete from public.rubric_criteria where question_id = 'ddd3fd8d-da72-41d0-88d6-5b1fea41c38d';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Write the output of the following C code.

#include <stdio.h>
void main()
{
    int i = 0, j = 0;
    for (i = 0; i < 5; i++)
    {
        for (j = 0; j < 4; j++)
        {
            if (i > 1)
                break;
        }
        printf("Hi \n");
    }
} (5 marks)', key_points = '[{"marks": 2, "point": "The printf is outside the inner loop, so it runs once per outer-loop pass"}, {"marks": 1.5, "point": "The break only ends the inner loop; the outer loop runs for i = 0 to 4 (5 times)"}, {"marks": 1.5, "point": "Output: ''Hi'' printed 5 times, each on a new line"}]'::jsonb where id = '79c198c2-d4c3-411e-be90-c0d828fc0e2d';
delete from public.rubric_criteria where question_id = '79c198c2-d4c3-411e-be90-c0d828fc0e2d';
