delete from public.rubric_criteria where question_id = '00ab9a1a-e8a8-40c0-b797-83529875741e';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Write HTML code to generate the following output (shown in the figure). Indicate table border as 1. (5 marks)', key_points = '[{"marks": 2, "point": "<table border=\"1\"> with a header row: Library, jQuery, Bootstrap, Modernizr (<th>)"}, {"marks": 1.5, "point": "Rows for Market Share (96.1%, 17.0%, 14.3%) and Absolute Usage (70.4%, 12.4%, 10.5%)"}, {"marks": 1.5, "point": "Last row: one cell spanning 4 columns (colspan=\"4\") with ''This exercise'' in bold (<b>) followed by ''is to demonstrate HTML skills.''"}]'::jsonb where id = 'eef1dc6f-bf8c-4151-8e01-85220e57ac43';
