update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Write a program to determine whether a given number is ODD or EVEN, and print the output accordingly. (5 marks)', key_points = '[{"marks": 2, "point": "Read the number (input)"}, {"marks": 1.5, "point": "Test with the modulus operator: number % 2 == 0"}, {"marks": 1.5, "point": "Print ''EVEN'' or ''ODD'' using if-else"}]'::jsonb where id = '289bb93d-4138-4dc8-ba9b-f12cc8fd479c';
