update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'What is DNS? State at least two types of DNS servers. (5 marks)', key_points = '[{"marks": 1.5, "point": "DNS (Domain Name System) translates human-readable domain names into IP addresses (and back); a distributed, hierarchical system using port 53"}, {"marks": 3.5, "point": "Two types, e.g. recursive resolver, root name server, TLD (top-level domain) server, authoritative name server (primary/ secondary), caching server"}]'::jsonb where id = '768f335a-7704-4c6c-a070-ebb2f673b6db';
delete from public.rubric_criteria where question_id = '768f335a-7704-4c6c-a070-ebb2f673b6db';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'What do the following acronyms stand for? (a) ASCII; (b) SNMP; (c) SSH. (5 marks)', key_points = '[{"marks": 2, "point": "(a) American Standard Code for Information Interchange"}, {"marks": 1.5, "point": "(b) Simple Network Management Protocol"}, {"marks": 1.5, "point": "(c) Secure Shell"}]'::jsonb where id = 'bfff93ff-5313-4959-85ad-05b97bb8e37e';
