update public.questions set marks = 5.0, estimated_seconds = 540, stem = '(a) Write an SQL statement to create a table ''Employee'' with the fields: EmployeeID of type int; FirstName, LastName, Address and City of type varchar with a maximum length of 255 characters. (2.5 marks)
(b) Write an SQL query to insert the following data into the table ''Employee'': EmployeeID = 2001, FirstName = Karma, Address = Bhutan, City = Thimphu. (2.5 marks)', key_points = '[{"marks": 2.5, "point": "(a) CREATE TABLE Employee (EmployeeID int, FirstName varchar(255), LastName varchar(255), Address varchar(255), City varchar(255));"}, {"marks": 2.5, "point": "(b) INSERT INTO Employee (EmployeeID, FirstName, Address, City) VALUES (2001, ''Karma'', ''Bhutan'', ''Thimphu'');"}]'::jsonb where id = 'f0f0e989-8163-44e3-9cac-6587a0635e15';
delete from public.rubric_criteria where question_id = 'f0f0e989-8163-44e3-9cac-6587a0635e15';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'There are two black counters and one white counter in a bag. Pema draws a counter from the bag without looking. He then replaces it and draws a second counter without looking.
(a) What is the probability that he draws two black counters? (2.5 marks)
(b) What is the probability that he draws at least one black counter? (2.5 marks)', key_points = '[{"marks": 2.5, "point": "(a) P(black) = 2/3 each time (with replacement), so P(two black) = 2/3 × 2/3 = 4/9"}, {"marks": 2.5, "point": "(b) P(at least one black) = 1 − P(no black) = 1 − (1/3 × 1/3) = 8/9"}]'::jsonb where id = '623d2d92-2873-406c-b0c8-888621afdfaf';
delete from public.rubric_criteria where question_id = '623d2d92-2873-406c-b0c8-888621afdfaf';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'What is deadlock in an operating system? How can you resolve a deadlock when you detect it? (2.5 + 2.5 = 5 marks)', key_points = '[{"marks": 2.5, "point": "Deadlock: two or more processes wait forever for resources held by each other; conditions - mutual exclusion, hold and wait, no preemption, circular wait"}, {"marks": 2.5, "point": "Recovery after detection: terminate (abort) one or all deadlocked processes, or preempt resources from a process (choose a victim, roll back to a safe state, avoid starvation)"}]'::jsonb where id = 'eb27399e-1cdd-465b-b4d4-6c20567992ca';
delete from public.rubric_criteria where question_id = 'eb27399e-1cdd-465b-b4d4-6c20567992ca';
