update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Give any four key features of object-oriented programming. (5 marks)', key_points = '[{"marks": 1.5, "point": "Encapsulation - data and methods bundled in a class, with data hidden behind an interface"}, {"marks": 1.5, "point": "Inheritance - a class reuses and extends another class"}, {"marks": 1, "point": "Polymorphism - the same method name behaves differently for different objects (overloading/ overriding)"}, {"marks": 1, "point": "Abstraction - showing only essential features and hiding details (also accepted: classes and objects)"}]'::jsonb where id = 'e6750a57-ce72-4a5b-b458-4f3041dd7d84';
delete from public.rubric_criteria where question_id = 'e6750a57-ce72-4a5b-b458-4f3041dd7d84';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Write the full forms of the following acronyms: (a) HTTP; (b) API; (c) SDLC; (d) ERP. (5 marks)', key_points = '[{"marks": 1.5, "point": "(a) HyperText Transfer Protocol"}, {"marks": 1.5, "point": "(b) Application Programming Interface"}, {"marks": 1, "point": "(c) Software Development Life Cycle"}, {"marks": 1, "point": "(d) Enterprise Resource Planning"}]'::jsonb where id = '477cef10-4f16-4165-8f42-3bb209495343';
