update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Write a function to reverse an integer using numeric operators and without using any arrays or other data structures. (5 marks)', key_points = '[{"marks": 1.5, "point": "Function takes an int and returns an int; result initialised to 0"}, {"marks": 1, "point": "Loop while n != 0: take the last digit with n % 10"}, {"marks": 2.5, "point": "Build the result with rev = rev * 10 + digit and drop the digit with n = n / 10; return rev"}]'::jsonb where id = '52d02c06-1773-497e-8151-3960ac40b08d';
delete from public.rubric_criteria where question_id = '52d02c06-1773-497e-8151-3960ac40b08d';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Convert the following:
(a) 210 - decimal into binary
(b) 41 - octal into binary
(c) 11110000 - binary into decimal
(d) 1228 - decimal into hexadecimal (5 marks)', key_points = '[{"marks": 1.5, "point": "(a) 210₁₀ = 11010010₂"}, {"marks": 1.5, "point": "(b) 41₈ = 100 001 = 100001₂"}, {"marks": 1, "point": "(c) 11110000₂ = 128 + 64 + 32 + 16 = 240₁₀"}, {"marks": 1, "point": "(d) 1228₁₀ = 4CC₁₆ (1228 = 4×256 + 12×16 + 12)"}]'::jsonb where id = 'ed8b7900-54c9-4066-b3fc-83296adfdb24';
delete from public.rubric_criteria where question_id = 'ed8b7900-54c9-4066-b3fc-83296adfdb24';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Write a function that takes an array of integers as an argument and returns a value based on the sums of the even and odd numbers in the array. Let X = the sum of the odd numbers in the array and let Y = the sum of the even numbers. The function should return X − Y. (5 marks)', key_points = '[{"marks": 1, "point": "Correct function header taking an array (and its size) and returning an int; variables for X and Y initialised to 0"}, {"marks": 2, "point": "Loop through every element and test odd/even with % 2"}, {"marks": 2, "point": "Add odd values to X and even values to Y; return X − Y"}]'::jsonb where id = 'c2f39b8b-8d71-4a4c-8c05-6add10c3867b';
delete from public.rubric_criteria where question_id = 'c2f39b8b-8d71-4a4c-8c05-6add10c3867b';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'What is Web 3.0? List any three key characteristics of Web 3.0. (5 marks)', key_points = '[{"marks": 1.5, "point": "Definition: the next generation of the web, decentralised, built on blockchain, giving users ownership of data, also semantic/ intelligent web"}, {"marks": 3.5, "point": "Three characteristics (1 each): decentralisation, blockchain and cryptocurrencies/ tokens, user ownership and control of data/ digital identity, trustless and permissionless, semantic web/ AI, smart contracts, interoperability, ubiquity (IoT)"}]'::jsonb where id = '1ef02d4e-6a4a-4044-ad37-c40f9fcc3646';
delete from public.rubric_criteria where question_id = '1ef02d4e-6a4a-4044-ad37-c40f9fcc3646';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Given a table named complaints with columns user_id, complaint_id and complaint_date, write an SQL query that returns only the users who have made more than three complaints. (5 marks)', key_points = '[{"marks": 2.5, "point": "SELECT user_id (with COUNT) FROM complaints GROUP BY user_id"}, {"marks": 2.5, "point": "HAVING COUNT(complaint_id) > 3 (not WHERE); correct syntax"}]'::jsonb where id = 'c41c912a-c060-4dd3-9231-0636fae19556';
delete from public.rubric_criteria where question_id = 'c41c912a-c060-4dd3-9231-0636fae19556';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'What is a Web Application Firewall (WAF)? State two differences between a WAF and a traditional network firewall. (5 marks)', key_points = '[{"marks": 2.5, "point": "WAF: filters, monitors and blocks HTTP/ HTTPS traffic to and from a web application, protecting against attacks such as SQL injection, XSS, CSRF (OWASP Top 10)"}, {"marks": 2.5, "point": "Differences (any two): layer 7 vs layers 3-4; inspects content of HTTP requests vs filters by IP/ port/ protocol; protects web apps vs whole network; rules on application attacks vs access rules"}]'::jsonb where id = '340b395c-3297-4187-8fe4-c8e60bc05875';
delete from public.rubric_criteria where question_id = '340b395c-3297-4187-8fe4-c8e60bc05875';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'What is an API key, and how is it used for authentication? (5 marks)', key_points = '[{"marks": 2, "point": "API key: a unique identifier/ secret token issued to a client application by an API provider"}, {"marks": 3, "point": "Use: sent with each request (header/ query parameter) - server checks it to identify and authorise the client, apply permissions, rate limits, track usage and billing; keep secret, use HTTPS, rotate/ revoke; not strong user authentication (combine with OAuth)"}]'::jsonb where id = 'c76a2a72-2da2-4ae9-b5d5-c31046b12e64';
delete from public.rubric_criteria where question_id = 'c76a2a72-2da2-4ae9-b5d5-c31046b12e64';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Explain the difference between black-box testing and white-box testing. (5 marks)', key_points = '[{"marks": 2.5, "point": "Black-box: tests functionality from the user''s view without knowledge of internal code - inputs/ outputs against requirements; techniques: equivalence partitioning, boundary value analysis; done by testers; e.g. system/ acceptance testing"}, {"marks": 2.5, "point": "White-box: tests internal structure, logic and code paths with knowledge of code - statement/ branch/ path coverage; done by developers; e.g. unit testing"}]'::jsonb where id = '9ad8b183-3a25-452e-91c5-42216355fffb';
delete from public.rubric_criteria where question_id = '9ad8b183-3a25-452e-91c5-42216355fffb';
update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Explain the differences between native and hybrid mobile applications. (5 marks)', key_points = '[{"marks": 2.5, "point": "Native: built for one platform with its language/ SDK (Swift/ Kotlin), best performance, full access to device features, separate codebases, higher cost"}, {"marks": 2.5, "point": "Hybrid: web technologies (HTML, CSS, JS) in a native wrapper (Ionic, Cordova) or cross-platform frameworks; one codebase for many platforms, faster/ cheaper development, lower performance/ limited native access, store distribution"}]'::jsonb where id = '75942716-9385-4b03-b30c-c71b48b0fd58';
delete from public.rubric_criteria where question_id = '75942716-9385-4b03-b30c-c71b48b0fd58';
