update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'Explain the difference between continuous integration, continuous delivery and continuous deployment. (5 marks)', key_points = '[{"marks": 2, "point": "Continuous integration: developers merge code often into a shared repository; each commit triggers automated build and tests"}, {"marks": 1.5, "point": "Continuous delivery: CI plus automated release pipeline; code is always deployable but release to production needs manual approval"}, {"marks": 1.5, "point": "Continuous deployment: every change that passes tests is released to production automatically, no manual step; example/diagram of the pipeline"}]'::jsonb where id = '9daf6f45-9e87-4a21-be2c-7cc6a0ebd90f';
