update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'A company tracks employee attendance using daily login hours. Write a program to count the number of employees who worked more than 8 hours in a day using any programming language. (5 marks)', key_points = '[{"marks": 1.5, "point": "Input/representation of hours (list, file or user input)"}, {"marks": 1.5, "point": "Loop over employees and compare with > 8 (strictly greater)"}, {"marks": 1, "point": "Counter variable correctly incremented"}, {"marks": 1, "point": "Output the count; correct syntax"}]'::jsonb where id = '74b97d5e-3d24-4205-b451-ea4fb3b709f1';
