update public.questions set marks = 5.0, estimated_seconds = 540, stem = 'You have just joined the office and you receive an email claiming to be from IT asking for your password to be entered in a shared link to resolve an urgent issue. Describe how you would identify whether it is a phishing email and prevent risks. (5 marks)', key_points = '[{"marks": 2.5, "point": "Warning signs: asks for password (IT never does), urgency/threat, suspicious sender address or link (hover to check domain), spelling errors"}, {"marks": 1.5, "point": "Do not click or reply; verify with IT through a known phone/channel; report to IT/security and delete"}, {"marks": 1, "point": "Prevention: MFA, change password if entered, security awareness training, spam filters"}]'::jsonb where id = '7ab81a44-6098-486b-8643-94ac1780001c';
